#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// First apply j_vec (inner), then i_vec (outer) to match C layout u[i][j]
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);
} tuning;


// initialization function
void init_array(auto U) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	// U: i x j
	traverser(U).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		U[state] = (num_t)(i + n - j) / (num_t)n;
	});
}


// computation kernel
//
// Optimizations compared to the original:
//  - Precompute the loop‑invariant combinations
//        col_center = 1 + 2*d
//        row_center = 1 + 2*a
//    so we avoid recomputing them in every inner iteration.
//  - Strength‑reduce the divisions in the forward sweeps:
//        denom = ...;
//        P = -c / denom;
//        Q = rhs / denom;
//    becomes
//        denom     = ...;
//        inv_denom = 1 / denom;         // one division
//        P         = -c * inv_denom;
//        Q         = rhs * inv_denom;   // two multiplications instead of
//                                      // another division.
//    This is algebraically equivalent while cheaper on modern CPUs.
//  - Keep the ADI ordering and all data dependencies identical to the
//    original code; only purely local arithmetic is changed.
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	num_t DX = 0, DY = 0, DT = 0;
	num_t B1 = 0, B2 = 0;
	num_t mul1 = 0, mul2 = 0;
	num_t a = 0, b = 0, c = 0, d = 0, e = 0, f = 0;

	// Precomputed “center” coefficients used in the Q updates:
	//   column sweep: (1 + 2*d)
	//   row sweep:    (1 + 2*a)
	num_t col_center = 0;
	num_t row_center = 0;

#pragma scop

	DX = SCALAR_VAL(1.0) / (num_t)n;
	DY = SCALAR_VAL(1.0) / (num_t)n;
	DT = SCALAR_VAL(1.0) / (num_t)tsteps;
	B1 = SCALAR_VAL(2.0);
	B2 = SCALAR_VAL(1.0);
	mul1 = B1 * DT / (DX * DX);
	mul2 = B2 * DT / (DY * DY);

	a = -mul1 / SCALAR_VAL(2.0);
	b = SCALAR_VAL(1.0) + mul1;
	c = a;
	d = -mul2 / SCALAR_VAL(2.0);
	e = SCALAR_VAL(1.0) + mul2;
	f = d;

	// Hoist loop‑invariant combinations used inside the sweeps
	col_center = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d; // 1 + 2*d
	row_center = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a; // 1 + 2*a

	for (std::size_t t = 1; t <= tsteps; t++) {
		// ------------------------------------------------------------------
		// Column sweep
		// ------------------------------------------------------------------
		traverser(U, V, P, Q)
			// work only on interior i = 1 .. n-2
			.order(noarr::slice<'i'>(1, n - 2))
			.template for_dims<'i'>([&](auto trav_i) {
				// Fixed column index for this 1D solve
				const std::size_t i = get_index<'i'>(trav_i.state());

				// Boundary conditions for column i
				V[noarr::idx<'i', 'j'>(0,     i)] = SCALAR_VAL(1.0);
				P[noarr::idx<'i', 'j'>(i,     0)] = SCALAR_VAL(0.0);
				Q[noarr::idx<'i', 'j'>(i,     0)] = V[noarr::idx<'i', 'j'>(0, i)];

				// Convenience traverser for interior j = 1 .. n-2 at this i
				auto trav_j = trav_i.order(noarr::slice<'j'>(1, n - 2));

				// Forward sweep in j: j = 1 .. n-2 (Thomas algorithm).
				trav_j.for_each([&](auto state) {
					// state contains current (i, j)
					auto prev = state - noarr::idx<'j'>(1); // (i, j-1)
					const std::size_t j = get_index<'j'>(state);

					// denom = a * P[i, j-1] + b
					const num_t denom     = a * P[prev] + b;
					const num_t inv_denom = SCALAR_VAL(1.0) / denom; // strength reduction

					// P[i, j] = -c / denom
					P[state] = -c * inv_denom;

					// U is accessed as U[j, i-1], U[j, i], U[j, i+1]
					const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
					const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i)];
					const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

					// Numerator in the original code:
					//   -d * u_j_im1
					// + (1 + 2*d) * u_j_i
					// - f * u_j_ip1
					// - a * Q[i, j-1]
					const num_t rhs =
						(-d * u_j_im1)
						+ col_center * u_j_i
						- f * u_j_ip1
						- a * Q[prev];

					// Q[i, j] = rhs / denom
					Q[state] = rhs * inv_denom;
				});

				// Bottom boundary at j = n-1
				V[noarr::idx<'i', 'j'>(n - 1, i)] = SCALAR_VAL(1.0);

				// Backward sweep in j: j = n-2 .. 1
				// Implemented as forward sweep over k = 1 .. n-2 with j = n-1-k.
				trav_j.for_each([&](auto state) {
					const std::size_t k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // runs n-2, n-3, ..., 1

					auto pij_state   = noarr::idx<'i', 'j'>(i,     j);
					auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

					V[noarr::idx<'i', 'j'>(j, i)] =
						P[pij_state] * V[vjp1i_state] + Q[pij_state];
				});
			});

		// ------------------------------------------------------------------
		// Row sweep
		// ------------------------------------------------------------------
		traverser(U, V, P, Q)
			// again, only interior i = 1 .. n-2
			.order(noarr::slice<'i'>(1, n - 2))
			.template for_dims<'i'>([&](auto trav_i) {
				const std::size_t i = get_index<'i'>(trav_i.state());

				// Boundary conditions for row i
				U[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(1.0);
				P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
				Q[noarr::idx<'i', 'j'>(i, 0)] = U[noarr::idx<'i', 'j'>(i, 0)];

				auto trav_j = trav_i.order(noarr::slice<'j'>(1, n - 2));

				// Forward sweep in j: j = 1 .. n-2
				trav_j.for_each([&](auto state) {
					auto prev = state - noarr::idx<'j'>(1); // (i, j-1)
					const std::size_t j = get_index<'j'>(state);

					// denom = d * P[i, j-1] + e
					const num_t denom     = d * P[prev] + e;
					const num_t inv_denom = SCALAR_VAL(1.0) / denom;

					// P[i, j] = -f / denom
					P[state] = -f * inv_denom;

					// V is accessed as V[i-1, j], V[i, j], V[i+1, j]
					const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
					const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
					const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

					// Numerator in the original code:
					//   -a * v_im1_j
					// + (1 + 2*a) * v_i_j
					// - c * v_ip1_j
					// - d * Q[i, j-1]
					const num_t rhs =
						(-a * v_im1_j)
						+ row_center * v_i_j
						- c * v_ip1_j
						- d * Q[prev];

					// Q[i, j] = rhs / denom
					Q[state] = rhs * inv_denom;
				});

				// Right boundary at j = n-1
				U[noarr::idx<'i', 'j'>(i, n - 1)] = SCALAR_VAL(1.0);

				// Backward sweep in j: j = n-2 .. 1
				trav_j.for_each([&](auto state) {
					const std::size_t k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // n-2, ..., 1

					auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

					U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
				});
			});
	}

#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	auto U = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto V = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ set_lengths);
	auto P = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize data
	init_array(U.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_adi(tsteps, U.get_ref(), V.get_ref(), P.get_ref(), Q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, U.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
