	num_t B1 = 0, B2 = 0;
	num_t mul1 = 0, mul2 = 0;
	num_t a = 0, b = 0, c = 0, d = 0, e = 0, f = 0;
	// Precomputed "center" coefficients used inside the inner loops
	num_t col_center = 0, row_center = 0;

#pragma scop

	// Discretization and ADI scheme coefficients (loop invariant)
	DX = SCALAR_VAL(1.0) / (num_t)n;
	DY = SCALAR_VAL(1.0) / (num_t)n;
	DT = SCALAR_VAL(1.0) / (num_t)tsteps;
	B1 = SCALAR_VAL(2.0);
	B2 = SCALAR_VAL(1.0);
	mul1 = B1 * DT / (DX * DX);
	mul2 = B2 * DT / (DY * DY);

	a = -mul1 / SCALAR_VAL(2.0);
	b = SCALAR_VAL(1.0) + mul1;
	c = a;
	d = -mul2 / SCALAR_VAL(2.0);
	e = SCALAR_VAL(1.0) + mul2;
	f = d;

	// These are (1 + 2*d) and (1 + 2*a) factored out of the inner loops
	col_center = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d;
	row_center = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a;

	for (std::size_t t = 1; t <= tsteps; t++) {
		// ============================================================
		// Column sweep: for each interior column i, solve along j
		// ============================================================
		//
		// Different i-columns are independent in this sweep:
		//  - we read U[*][i-1..i+1] at fixed time t,
		//  - we write only V[*][i] and P[i][*], Q[i][*].
		// Therefore we can parallelize across i while keeping the
		// Thomas recurrences in j strictly sequential.

