			// work only on interior columns i = 1 .. n-2
			.order(noarr::slice<'i'>(1, n - 2));

#ifdef _OPENMP
		#pragma omp parallel for schedule(static)
#endif
		for (auto trav_i : col_trav) {
			// trav_i has i fixed and iterates over all j for that i
			const auto i_state = trav_i.state();
			const std::size_t i = get_index<'i'>(i_state);

			// Boundary conditions for column i
			V[noarr::idx<'i', 'j'>(0,      i)] = SCALAR_VAL(1.0);
			P[noarr::idx<'i', 'j'>(i,      0)] = SCALAR_VAL(0.0);
			Q[noarr::idx<'i', 'j'>(i,      0)] = V[noarr::idx<'i', 'j'>(0, i)];

			// Forward sweep along j: j = 1 .. n-2 (Thomas algorithm)
			trav_i.order(noarr::slice<'j'>(1, n - 2)).for_each([&](auto state) {
				auto prev = state - noarr::idx<'j'>(1);

				const num_t denom     = a * P[prev] + b;
				const num_t inv_denom = SCALAR_VAL(1.0) / denom;

				P[state] = -c * inv_denom;

				const std::size_t j = get_index<'j'>(state);

				const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
				const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i    )];
				const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

				const num_t rhs =
					-d * u_j_im1 +
					col_center * u_j_i -
					f * u_j_ip1 -
					a * Q[prev];

				Q[state] = rhs * inv_denom;
			});

			// Bottom boundary of column i
			V[noarr::idx<'i', 'j'>(n - 1, i)] = SCALAR_VAL(1.0);

