			// mapping to j = n-1-k, but the iteration itself is still driven
			// by a noarr traverser so that dependencies in j are preserved.
			trav_i.order(noarr::slice<'j'>(1, n - 2)).for_each([&](auto state) {
				const std::size_t k = get_index<'j'>(state);
				const std::size_t j = n - 1 - k; // n-2, n-3, ..., 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

				V[noarr::idx<'i', 'j'>(j, i)] =
					P[pij_state] * V[vjp1i_state] + Q[pij_state];
			});
		}

		// ============================================================
		// Row sweep: for each interior row i, solve along j
		// ============================================================
		//
		// Here we update U in place using the intermediate V.
		// Again, different rows i are independent (for fixed t),
		// but each row has a j-recurrence, so only i is parallelized.

		auto row_trav = traverser(U, V, P, Q)
			.order(noarr::slice<'i'>(1, n - 2));

#ifdef _OPENMP
		#pragma omp parallel for schedule(static)
#endif
		for (auto trav_i : row_trav) {
			const auto i_state = trav_i.state();
			const std::size_t i = get_index<'i'>(i_state);

			// Boundary conditions for row i
			U[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(1.0);
			P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
			Q[noarr::idx<'i', 'j'>(i, 0)] = U[noarr::idx<'i', 'j'>(i, 0)];

			// Forward sweep in j: j = 1 .. n-2
			trav_i.order(noarr::slice<'j'>(1, n - 2)).for_each([&](auto state) {
				auto prev = state - noarr::idx<'j'>(1);

				const num_t denom     = d * P[prev] + e;
				const num_t inv_denom = SCALAR_VAL(1.0) / denom;

				P[state] = -f * inv_denom;

				const std::size_t j = get_index<'j'>(state);

				const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
				const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
				const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

				const num_t rhs =
					-a * v_im1_j +
					row_center * v_i_j -
					c * v_ip1_j -
					d * Q[prev];

				Q[state] = rhs * inv_denom;
			});

			// Right boundary of row i
			U[noarr::idx<'i', 'j'>(i, n - 1)] = SCALAR_VAL(1.0);

			// Backward sweep in j: j = n-2 .. 1
			trav_i.order(noarr::slice<'j'>(1, n - 2)).for_each([&](auto state) {
				const std::size_t k = get_index<'j'>(state);
				const std::size_t j = n - 1 - k; // n-2, ..., 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

				U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
			});
		}
	}

#pragma endscop
