	// Time stepping is inherently sequential.
	for (std::size_t t = 1; t <= tsteps; t++) {

		// ==========================================================
		// Column sweep: implicit solve along j for each interior i
		// ==========================================================
		// We traverse only interior i ∈ {1, …, n−2}.
		auto col_trav = traverser(U, V, P, Q)
			.order(noarr::slice<'i'>(1, n - 2));

		// Different i-lines are independent in this sweep, so we can
		// parallelize over the outermost traverser dimension (i).
		#pragma omp parallel for schedule(static)
		for (auto trav_i : col_trav) {
			auto state_i = trav_i.state();
			const std::size_t i = get_index<'i'>(state_i);

			// Boundary conditions for column i
			V[noarr::idx<'i', 'j'>(0,     i)] = SCALAR_VAL(1.0);
