						(-d * u_j_im1)
						+ col_center * u_j_i
						- f * u_j_ip1
						- a * Q[prev];

					Q[state] = rhs * inv_denom;
				});

			// Bottom boundary at j = n-1 for column i
			V[noarr::idx<'i', 'j'>(n - 1, i)] = SCALAR_VAL(1.0);

			// Backward sweep in j: j = n-2 .. 1
			// Implemented as a forward traversal over k = 1 .. n-2,
			// mapping k → j = n-1-k exactly as in the original code.
			trav_i
				.order(noarr::slice<'j'>(1, n - 2))
				.for_each([&](auto state) {
					const std::size_t k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // j runs n-2, n-3, ..., 1

					auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

					V[noarr::idx<'i', 'j'>(j, i)] =
						P[pij_state] * V[vjp1i_state] + Q[pij_state];
				});
		}

		// ==========================================================
		// Row sweep: implicit solve along j for each interior i
		// ==========================================================
		// Again operate only on interior i ∈ {1, …, n−2}.
		auto row_trav = traverser(U, V, P, Q)
			.order(noarr::slice<'i'>(1, n - 2));

		#pragma omp parallel for schedule(static)
		for (auto trav_i : row_trav) {
			auto state_i = trav_i.state();
			const std::size_t i = get_index<'i'>(state_i);

			// Boundary conditions for row i
			U[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(1.0);
			P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
			Q[noarr::idx<'i', 'j'>(i, 0)] = U[noarr::idx<'i', 'j'>(i, 0)];

			// Forward sweep in j: j = 1 .. n-2
			trav_i
				.order(noarr::slice<'j'>(1, n - 2))
				.for_each([&](auto state) {
					auto prev = state - noarr::idx<'j'>(1);
					const std::size_t j = get_index<'j'>(state);

					// denom = d * P[i, j-1] + e;
					const num_t denom     = d * P[prev] + e;
					const num_t inv_denom = SCALAR_VAL(1.0) / denom;

					P[state] = -f * inv_denom;

					// V is indexed as V[i-1, j], V[i, j], V[i+1, j]
					const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
					const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
					const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

					const num_t rhs =
						(-a * v_im1_j)
						+ row_center * v_i_j
						- c * v_ip1_j
						- d * Q[prev];

					Q[state] = rhs * inv_denom;
				});

			// Right boundary at j = n-1 for row i
			U[noarr::idx<'i', 'j'>(i, n - 1)] = SCALAR_VAL(1.0);

			// Backward sweep in j: j = n-2 .. 1
			trav_i
				.order(noarr::slice<'j'>(1, n - 2))
				.for_each([&](auto state) {
					const std::size_t k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // j runs n-2, ..., 1

					auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

					U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
				});
		}
	}

#pragma endscop
}

